// consoleQuotaCheck reports an error when the named proxy has exhausted its
// configured traffic quota. It is a no-op unless the console metrics layer is
// installed and the proxy has a quota rule.
func consoleQuotaCheck(proxyName string) error {
	cm := metrics.ConsoleMetricsInstance()
	if cm == nil {
		return nil
	}
	return cm.CheckQuota(proxyName)
}

func (ctl *Control) handlePing(m msg.Message) {

// frp-console: install auditing + traffic quota before the service starts.
installConsoleAudit()

svr, err := server.NewService(cfg)

// frp-console: report status to the panel when configured via env.
startConsoleHeartbeat(func() map[string][]proxyStatusLite {
	exp := svr.StatusExporter()
	out := make(map[string][]proxyStatusLite)
	pcfgs, _, err := aggregator.Load()
	if err != nil {
		return out
	}
	for _, pxy := range pcfgs {
		base := pxy.GetBaseConfig()
		entry := proxyStatusLite{Name: base.Name, Type: base.Type, Status: "unknown"}
		if st, ok := exp.GetProxyStatus(base.Name); ok {
			entry.Status = st.Phase
			entry.Err = st.Err
		}
		out[base.Type] = append(out[base.Type], entry)
	}
	return out
})

